import json


def _check_duplicates(value):
    """Recursively check for duplicate object keys at any nesting depth."""
    if isinstance(value, dict):
        seen = set()
        for key in value:
            if key in seen:
                raise ValueError(f"Duplicate object key: {key!r}")
            seen.add(key)
            _check_duplicates(value[key])
    elif isinstance(value, list):
        for item in value:
            _check_duplicates(item)


def parse_jsonl(text):
    """Parse newline-delimited JSON text into a list of decoded values.

    Whitespace-only lines are skipped. Malformed non-blank JSON lines raise
    ValueError. Duplicate object keys at any nesting depth raise ValueError.
    """
    results = []
    for line in text.splitlines():
        if line.strip() == "":
            continue
        value = json.loads(line)
        _check_duplicates(value)
        results.append(value)
    return results

